<?php
require_once __DIR__.'/../delivery_common.php';$uid=dc_uid();if(!$uid)die('Login required');
$q=$pdo->prepare("SELECT COALESCE(SUM(collected_amount),0) c FROM delivery_collections WHERE delivery_user_id=? AND handover_status='held'");$q->execute([$uid]);$held=(float)$q->fetchColumn();
$q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM delivery_tips WHERE delivery_user_id=? AND status='confirmed'");$q->execute([$uid]);$tips=(float)$q->fetchColumn();
$q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM delivery_earnings WHERE staff_user_id=? AND status='credited'");$q->execute([$uid]);$earn=(float)$q->fetchColumn();
if($_SERVER['REQUEST_METHOD']==='POST'&&$held>0){$retain=max(0,min($held,(float)($_POST['retain']??0)));$forward=$held-$retain;$pdo->beginTransaction();try{$pdo->prepare("INSERT INTO delivery_settlements(delivery_user_id,collection_total,retained_delivery_earning,retained_tips,amount_forwarded,method,reference_no) VALUES(?,?,?,?,?,?,?)")->execute([$uid,$held,$retain,$tips,$forward,$_POST['method'],trim($_POST['ref']??'')]);$pdo->prepare("UPDATE delivery_collections SET handover_status='submitted',submitted_at=NOW() WHERE delivery_user_id=? AND handover_status='held'")->execute([$uid]);$pdo->commit();header("Location: settlement.php");exit;}catch(Throwable $e){$pdo->rollBack();$err=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><title>Delivery Settlement</title><style>body{font-family:Segoe UI;background:#f4f7f5}.w{max-width:760px;margin:30px auto}.c{background:white;border:1px solid #dfe8e3;padding:20px;border-radius:15px;margin:12px}.n{font-size:30px;font-weight:800}input,select,button{padding:11px;margin:5px;border:1px solid #ccd9d1;border-radius:8px}button{background:#176b4b;color:white;border:0}</style></head><body><div class="w"><a href="<?=htmlspecialchars(dc_back())?>">← Back</a><div class="c"><h2>Daily Delivery Settlement</h2><p>Cash/MFS collected and not yet submitted</p><div class="n">৳<?=number_format($held,2)?></div><p>Recorded delivery earning: ৳<?=number_format($earn,2)?> · Tips: ৳<?=number_format($tips,2)?></p></div><div class="c"><h3>Forward collection to company</h3><form method="post"><input type="number" step=".01" min="0" max="<?=$held?>" name="retain" value="0" placeholder="Allowed earning to retain"><select name="method"><option value="cash_handover">Cash handover</option><option value="bank">Bank</option><option value="bkash">bKash</option><option value="nagad">Nagad</option><option value="other_mfs">Other MFS</option></select><input name="ref" placeholder="Reference / transaction ID"><button <?=$held<=0?'disabled':''?>>Submit Settlement</button></form><small>Manager/Owner verifies the submitted settlement. Tips and earnings remain separately auditable.</small></div></div></body></html>